nd":"classic","background_color":"#02010100","background_size":"cover","background_overlay_opacity":{"unit":"px","size":0,"sizes":[]}},"elements":[{"id":"5755af8","elType":"container","settings":{"content_width":"full","width_laptop":{"unit":"%","size":90,"sizes":[]},"width_tablet":{"unit":"%","size":"","sizes":[]},"width_mobile":{"unit":"%","size":"","sizes":[]},"boxed_width_laptop":{"unit":"%","size":40,"sizes":[]},"boxed_width_tablet":{"unit":"%","size":"","sizes":[]},"boxed_width_mobile":{"unit":"%","size":"","sizes":[]},"_flex_size":"shrink"},"elements":[{"id":"a068bb2","elType":"widget","settings":{"title":"faq","title_color":"#FA9E09","typography_typography":"custom","typography_font_family":"Exo","typography_font_size":{"unit":"px","size":16,"sizes":[]},"typography_font_weight":"700","typography_text_transform":"uppercase","typography_line_height":{"unit":"px","size":17.60000000000000142108547152020037174224853515625,"sizes":[]},"typography_letter_spacing":{"unit":"px","size":-0.08000000000000000166533453693773481063544750213623046875,"sizes":[]},"hide_tablet":"hidden-tablet","hide_mobile":"hidden-mobile"},"elements":[],"widgetType":"heading"},{"id":"83b013f","elType":"widget","settings":{"title":"Często zadawane pytania","typography_typography":"custom","typography_font_family":"Exo","typography_font_size":{"unit":"px","size":40,"sizes":[]},"typography_font_weight":"600","typography_line_height":{"unit":"px","size":48,"sizes":[]},"__globals__":{"title_color":"globals/colors?id=5c67747"},"align_tablet":"center","typography_font_size_mobile":{"unit":"px","size":38,"sizes":[]},"typography_line_height_mobile":{"unit":"px","size":45.60000000000000142108547152020037174224853515625,"sizes":[]}},"elements":[],"widgetType":"heading"}],"isInner":true},{"id":"3bc0158","elType":"container","settings":{"flex_gap":{"column":"24","row":"24","isLinked":true,"unit":"px","size":24},"boxed_width_laptop":{"unit":"%","size":100,"sizes":[]},"boxed_width_tablet":{"unit":"%","size":"","sizes":[]},"boxed_width_mobile":{"unit":"%","size":"","sizes":[]},"boxed_width":{"unit":"%","size":"","sizes":[]}},"elements":[{"id":"b3e19b0","elType":"widget","settings":{"ekit_accordion_items":[{"acc_title":"Powierzam Wam wrażliwy obszar/dział w mojej firmie, skąd mogę wiedzieć, że ta współpraca się powiedzie?","acc_content":"<p>Zanim rozpoczniemy współpracę zawsze startujemy do ok 2 godzinnych darmowych konsultacji. To czas, gdy wzajemnie się poznajemy oraz oceniamy, czy jesteśmy w stanie pomóc. Nie podejmujemy się projektów, na które nie mamy sprawdzonego, konkretnego rozwiązania - polecamy wtedy zaprzyjaźnioną firmę specjalizującą się w danej problematyce.</p>","ekit_acc_is_active":"","_id":"e9d6d03"},{"acc_title":"Wasze doświadczenie jest skupione wokół branży IT i Digital, ja  prowadzę mała firmę w innej branży - jak możecie mi pomóc?","acc_content":"<p>Wyzwania w obszarze ludzkim są podobne w różnych branżach to, co jest istotniejsze to skala organizacji i jej stopień rozwoju. Na pierwszych, darmowych konsultacjach badamy potrzeby naszych klientów i rozmawiamy o potencjalnych rozwiązaniach, wspólnie oceniamy czy wpisują się one w daną organizację. Mamy sprawdzone metody, które wdrażaliśmy w kancelariach, software housach, SaaS, a nawet klubie fitness.</p>","ekit_acc_is_active":"","_id":"eb0fabe"},{"_id":"90e6d49","acc_title":"Jak szybko możemy zacząć współpracę? ","acc_content":"<p>W zależności od potrzeb proponujemy konsultanta, który ma największe kompetencje w wymaganym obszarze, co średnio trwa 2-3 tyg.</p>"},{"_id":"1c0a2cf","acc_title":"Ile kosztuje podjęcie współpracy z Interim Managerem?","acc_content":"<p>Koszt zależy od zakresu i intensywności współpracy. Standardowa współpraca zamyka się w około 2- 3 dni roboczych w tyg. pracy Interim Managera. Taka współpraca może kosztować od kilku do kilkunastu tysięcy miesięcznie.</p>"},{"_id":"5143ff2","acc_title":"Na jak długo możemy podpisać umowę? Co, jeśli chcę tylko przetestować usługę HR na godziny czy Interim Management. ","acc_content":"<p>Minimalny okres współpracy w HR na godziny to miesiąc, a Interim Management to kwartał. Po przejściu na stałą współpracę podpisujemy ją zazwyczaj na czas nieokreślony z miesięcznym terminem wypowiedzenia.</p>"},{"_id":"234731c","acc_title":"Czy mogę przesuwać godziny w ramach miesięcy?","acc_content":"<p>Tak, przy stałej współpracy czyli takiej, gdzie umowę podpisujemy na czas nieokreślony przy zachowaniu miesięcznego okresu wypowiedzenia. (W takiej formie współpracujemy z 90% naszych klientów). Wiemy, że zdarzają się miesiące, które wymagają chwilowego większego zaangażowania konsultanta, dlatego przesuwamy godziny pomiędzy miesiącami by zaspokoić potrzeby organizacji.</p>"},{"_id":"10640bd","acc_title":"Czy mogę zmienić zakres pakietu?","acc_content":"<p>Oczywiście, zakres współpracy dostosowujemy do potrzeb organizacji. W razie potrzeby zarówno zakres jak i liczba godzin może zostać dostosowany lub zmienić się w trakcie współpracy.</p>"},{"_id":"cbc812f","acc_title":"Czy zawsze pracuje z tym samym konsultantem/interim managerem? ","acc_content":"<p>W ramach współpracy interim management dedykowany jest jeden konkretny konsultant.</p>"}],"ekit_accordion_open_first_slide":"","ekit_accordion_display_loop_count":"","ekit_accordion_right_icons":{"value":{"url":"https://businessquest.pl/wp-content/uploads/2023/11/add.svg","id":1045},"library":"svg"},"ekit_accordion_right_icon_actives":{"value":{"url":"https://businessquest.pl/wp-content/uploads/2023/11/remove.svg","id":1046},"library":"svg"},"ekit_accordion_title_typography_typography":"custom","ekit_accordion_title_typography_font_family":"Exo","ekit_accordion_title_typography_font_size":{"unit":"px","size":16,"sizes":[]},"ekit_accordion_title_typography_font_weight":"400","ekit_accordion_title_typography_line_height":{"unit":"px","size":25.60000000000000142108547152020037174224853515625,"sizes":[]},"ekit_accordion_background_background":"classic","ekit_accordion_backgrou