":24,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"d6a2e73","elType":"widget","settings":{"editor":"<div class="content_panel--textContent--dJDd8 common--well--u4Uom" dir="auto" data-testid="textContent">Jeśli szukasz wsparcia w obszarze rozwoju swojego biznesu i zespołów umów się z nami na bezpłatne konsultacje. Poznamy się i wspólnie wypracujemy rozwiązania dla Twojej firmy. Jeśli potrzebujesz odpowiedzi szybciej wypełnij ankietę - pozwoli Ci to szybko uzyskać konkretną propozycję współpracy.</div>","text_color":"#F6F4EE80","typography_typography":"custom","typography_font_family":"Exo","typography_font_size":{"unit":"px","size":16,"sizes":[]},"typography_font_weight":"400","typography_line_height":{"unit":"px","size":24,"sizes":[]},"text_shadow_text_shadow_type":"yes","_padding":{"unit":"px","top":"0","right":"0","bottom":"80","left":"0","isLinked":false},"align_mobile":"center","typography_font_size_mobile":{"unit":"px","size":16,"sizes":[]},"typography_line_height_mobile":{"unit":"px","size":21,"sizes":[]},"_padding_tablet":{"unit":"px","top":"0","right":"0","bottom":"40","left":"0","isLinked":false}},"elements":[],"widgetType":"text-editor"},{"id":"df1c753","elType":"container","settings":{"content_width":"full","width":{"unit":"%","size":100,"sizes":[]},"flex_direction":"row","flex_justify_content":"flex-start","flex_gap":{"column":"44","row":"44","isLinked":true,"unit":"px","size":44},"flex_direction_tablet":"column","flex_align_items_tablet":"center","flex_gap_tablet":{"column":"17","row":"17","isLinked":true,"unit":"px","size":17}},"elements":[{"id":"3189f3b","elType":"widget","settings":{"text":"umów się","icon_indent":{"unit":"px","size":0,"sizes":[]},"typography_typography":"custom","typography_font_family":"Exo","typography_font_size":{"unit":"px","size":14,"sizes":[]},"typography_font_weight":"700","typography_text_transform":"uppercase","typography_letter_spacing":{"unit":"px","size":0.75,"sizes":[]},"background_color":"#EF087A","border_r