#interim_box_hov:hover::after {

      width: 102%;
    background: linear-gradient(180deg, rgba(239, 8, 122, 0.41) 0%, rgba(250, 158, 9, 0.04) 100%);
      transition: all 0.4s ease-out;
}

#interim_box_hov:hover #inter_box_text {
    color: #FFFFFF;
}

.interim_box_hov_circle {
    opacity: 0;
    transition: all 0.4s ease-out;

}
#interim_box_hov:hover .interim_box_hov_circle {
    opacity: 1;

}
@media (max-width: 1024px) {
  .interim_box_hov_circle {
    opacity: 1;

}  
